package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import com.lianxibu.site.repository.jobs.*;import com.lianxibu.site.service.jobs.OperationalRuleEngine.*;import java.time.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.Test;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="B44_MYSQL",matches="true")
class ApiMonitoringCycleMySqlTest {
 @Test void actualOriginalMysqlAckLossPermanentWindowAlarmRestartAndNativeCaptureLoss(){
  try(var f=new PooledResultJdbcMySqlFixture()){f.fixture();f.jdbc.execute("DROP TABLE IF EXISTS runtime_settings");f.jdbc.execute("CREATE TABLE runtime_settings(setting_key VARCHAR(64) PRIMARY KEY,value_json JSON NOT NULL,revision BIGINT NOT NULL,updated_at DATETIME(6) NOT NULL)");var clock=new OperationalPersistenceFixture.MutableClock();clock.now=ApiWindowWatermarkTest.START.minusSeconds(300);var nanos=new AtomicLong();var probe=new ProcessApiRuntimeTelemetry(clock,nanos::get,clock.now.minusSeconds(300),ApiWindowWatermarkTest.EPOCH);try(var capture=probe.openCapture()){
   for(int n=0;n<100;n++)probe.completedHttp(n<10?503:200);clock.now=clock.now.plusSeconds(300);nanos.set(300000000000L);var calls=new AtomicInteger();var store=new OperationalJdbcStore(new JdbcOperationalSummaries(f.source),new JdbcJobRecords(f.source),clock);var monitor=new OperationalMonitoringService(store,()->new OperationalMonitoringService.Configuration(1,MonitoringFixtures.complete()),f.writes,clock);java.util.function.Supplier<ApiMonitoringCycle> cycle=()->{var value=new ApiMonitoringCycle(ApiWindowWatermarkTest.KEY,()->{calls.incrementAndGet();assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return probe.read();},store,monitor,clock);value.start();return value;};f.tx.ackLost=true;assertEquals(ApiMonitoringCycle.Outcome.SAMPLED,cycle.get().tick());State actual=store.read(ApiWindowWatermarkTest.KEY);assertEquals(Level.CRITICAL,actual.level());assertEquals(1,actual.counters().get("api_required"));assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='ops_rule'",Integer.class));assertEquals(ApiMonitoringCycle.Outcome.ALREADY_SAMPLED,cycle.get().tick());assertEquals(1,calls.get());capture.close();clock.now=clock.now.plusSeconds(60);nanos.addAndGet(60000000000L);cycle.get().tick();var rebuilt=new OperationalJdbcStore(new JdbcOperationalSummaries(f.source),new JdbcJobRecords(f.source),clock).read(ApiWindowWatermarkTest.KEY);assertEquals(Status.TELEMETRY_UNKNOWN,rebuilt.status());assertEquals(Level.CRITICAL,rebuilt.level());assertEquals(actual.counters().get("api_end_micros"),rebuilt.counters().get("api_end_micros"));assertEquals(actual.counters().get("api_f0"),rebuilt.counters().get("api_f0"));
  }}
 }
}
